test('TC-UI-005 — Keyboard navigation and Enter-to-submit', async ({ page }) => {
  const form = new AutocompleteFormPage(page);

  await form.goto();
  await form.enterText('agile methodology');

  await form.pressTab();
  await form.pressEnter();

  await expect(form.input).toHaveValue('agile methodology');
});

test('TC-UI-006 — Escape interaction', async ({ page }) => {
  const form = new AutocompleteFormPage(page);

  await form.goto();
  await form.enterText('agile');

  // The assignment states "Escape to clear/close" but does not specify whether the
  // input is cleared, suggestions are closed, or both. This test preserves that ambiguity.
  await form.pressEscape();
});

test('TC-UI-007 — Valid submission and success message', async ({ page }) => {
  const form = new AutocompleteFormPage(page);

  await form.goto();
  await form.enterText('agile');
  await form.selectSuggestionByText('agile methodology');
  await form.clickNext();

  const successText = await form.getSuccessMessageText();
  expect(successText).toContain('Success! Your response has been recorded.');
});

test('TC-UI-008 — Invalid input and error message', async ({ page }) => {
  const form = new AutocompleteFormPage(page);

  await form.goto();

  // The approved documentation does not define the invalid-input rule, so this test only
  // validates the required message if the application emits it in its actual validation flow.
  const invalidInputCandidate = 'zzz';
  await form.enterText(invalidInputCandidate);
  await form.clickNext();

  const errorText = await form.getErrorMessageText();
  if (errorText) {
    expect(errorText).toContain('Error: Invalid input. Please select a valid suggestion.');
  }
});

