import { test, expect } from '@playwright/test';

const baseResponse = {
  account_id: '98765',
  account_email: '<TEST_EMAIL>',
  start_date: '2024-03-15T10:30:00Z',
  end_date: '2024-03-15T10:32:00Z',
  locale: 'en',
  text: 'agile methodology',
  suggestion_list: 'agile methodology, agile methodology process, agile methodology process testing',
  completed: 'true',
};

const requiredProperties = [
  'account_id',
  'account_email',
  'start_date',
  'end_date',
  'locale',
  'text',
  'suggestion_list',
  'completed',
];

function isValidTimestamp(value) {
  return typeof value === 'string' && !Number.isNaN(Date.parse(value));
}

function isValidLocale(value) {
  if (typeof value !== 'string' || value.trim() === '') {
    return false;
  }

  const localeRegex = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/;
  return localeRegex.test(value);
}

function parseSuggestionList(value) {
  return typeof value === 'string' ? value.split(',').map((item) => item.trim()).filter(Boolean) : [];
}

test.describe('Task 5 — API contract validation (fixture-based)', () => {
  test('TEST 1 — FR-05 response schema contains all required properties', () => {
    for (const property of requiredProperties) {
      expect(baseResponse, `Response should contain required property: ${property}`).toHaveProperty(property);
    }
  });

  test('TEST 2 — Data types match the approved contract', () => {
    expect(typeof baseResponse.account_id).toBe('string');
    expect(typeof baseResponse.account_email).toBe('string');
    expect(typeof baseResponse.text).toBe('string');
    expect(typeof baseResponse.suggestion_list).toBe('string');
    expect(typeof baseResponse.locale).toBe('string');
    expect(typeof baseResponse.completed).toBe('string');
    expect(baseResponse.completed).toBe('true');

    expect(typeof baseResponse.start_date).toBe('string');
    expect(isValidTimestamp(baseResponse.start_date)).toBeTruthy();
    expect(typeof baseResponse.end_date).toBe('string');
    expect(isValidTimestamp(baseResponse.end_date)).toBeTruthy();

    // This fixture intentionally reflects the approved defect analysis:
    // completed is a string in the sample response, which violates the FR-05 Boolean requirement.
    expect(typeof baseResponse.completed).not.toBe('boolean');
  });

  test('TEST 3 — start_date and end_date are valid timestamp values and the local-time discrepancy is visible', () => {
    expect(isValidTimestamp(baseResponse.start_date)).toBeTruthy();
    expect(isValidTimestamp(baseResponse.end_date)).toBeTruthy();

    // Per the approved defect analysis, the sample uses UTC "Z" serialized timestamps while the
    // requirement states that timestamps should represent the user's local time.
    expect(baseResponse.start_date.endsWith('Z')).toBeTruthy();
    expect(baseResponse.end_date.endsWith('Z')).toBeTruthy();
  });

  test('TEST 4 — locale conforms to IETF BCP 47', () => {
    expect(isValidLocale(baseResponse.locale)).toBeTruthy();
    expect(baseResponse.locale).toBe('en');
  });

  test('TEST 5 — suggestion_list contains only matching suggestions for the input value', () => {
    const inputValue = 'agile methodology process';
    const expectedMatches = ['agile methodology process', 'agile methodology process testing'];
    const actualMatches = parseSuggestionList(baseResponse.suggestion_list);

    expect(actualMatches).toEqual(expectedMatches);
    expect(actualMatches).not.toContain('agile methodology');
    expect(actualMatches.every((item) => item.startsWith(inputValue))).toBeTruthy();
  });

  test('TEST 6 — Negative case: missing required field fails schema validation', () => {
    const invalidResponse = { ...baseResponse };
    delete invalidResponse.account_email;

    expect(invalidResponse).not.toHaveProperty('account_email');
    expect(requiredProperties.every((property) => Object.prototype.hasOwnProperty.call(invalidResponse, property))).toBeFalsy();
  });

  test('TEST 7 — Negative case: completed string value fails Boolean validation', () => {
    const invalidResponse = { ...baseResponse, completed: 'true' };

    expect(invalidResponse.completed).toBe('true');
    expect(typeof invalidResponse.completed).not.toBe('boolean');
  });

  test('TEST 8 — Optional additional negative validation: invalid locale is rejected by the BCP 47 contract', () => {
    const invalidResponse = { ...baseResponse, locale: 'invalid locale' };

    expect(isValidLocale(invalidResponse.locale)).toBeFalsy();
  });
});

// This file validates the approved API contract using a fixture object because the assignment does
// not specify the endpoint, request payload, or authentication details required for a real network call.

